CREATE TABLE v96033 (v96034 INT NOT NULL, v96035 VARCHAR(10) NOT NULL, PRIMARY KEY (v96035)) AS SELECT LOOKUP('POINT(61 133)'), R_SUBSTR('Find pattern'), LOCALTIME(3), CURRENT_TIME(5), CURRENT_TIMESTAMP(0), SLEEP(@long_query_time + 1), UNCOMPRESSED_LENGTH(x3), FIELD('b', 'A' COLLATE latin1_bin, 'B')